314	        String evidenceKey = uniqueKey("EV");
315	        intake("alice", uniqueKey("CMD"), evidenceKey);
316	        assertThat(inspect("mallory", evidenceKey, uniqueKey("CMD"), true)
317	                .getResponse().getStatus()).isEqualTo(409);
