331	        MvcResult result = mockMvc.perform(get("/api/evidence/transferable")
332	                        .header(ACTOR_HEADER, actor))
333	                .andReturn();
334	        assertThat(result.getResponse().getStatus()).isEqualTo(200);
335	        JsonNode list = objectMapper.readTree(result.getResponse().getContentAsString());
336	        assertThat(list).hasSize(2);
337	        assertThat(list.findValuesAsText("evidenceKey")).containsExactlyInAnyOrder(ev1, ev3);
338	    }
