340	    @Test
341	    void custodyChainAppendsHistoryInOrder() throws Exception {
342	        String evidenceKey = uniqueKey("EV");
343	        intake("alice", uniqueKey("CMD"), evidenceKey);
344	        inspect("alice", evidenceKey, uniqueKey("CMD"), true);
345	        initiate("alice", evidenceKey, uniqueKey("CMD"), "bob");
346	        decide("bob", evidenceKey, uniqueKey("CMD"), "accept");
347	        inspect("bob", evidenceKey, uniqueKey("CMD"), true);
348	
349	        JsonNode chain = chain(evidenceKey);
350	        assertThat(chain.get("evidence").get("custodianId").asText()).isEqualTo("bob");
351	        assertThat(chain.get("transfers")).hasSize(1);
352	        assertThat(chain.get("inspections")).hasSize(2);
353	        assertThat(chain.get("inspections").get(0).get("inspectorId").asText()).isEqualTo("alice");
354	        assertThat(chain.get("inspections").get(1).get("inspectorId").asText()).isEqualTo("bob");
355	    }
