357	    @Test
358	    void transferAcceptIdempotentReplayDoesNotChangeCustodianTwice() throws Exception {
359	        String evidenceKey = uniqueKey("EV");
360	        String acceptKey = uniqueKey("CMD");
361	        intake("alice", uniqueKey("CMD"), evidenceKey);
362	        initiate("alice", evidenceKey, uniqueKey("CMD"), "bob");
363	
364	        MvcResult first = decide("bob", evidenceKey, acceptKey, "accept");
365	        MvcResult replay = decide("bob", evidenceKey, acceptKey, "accept");
366	        assertThat(first.getResponse().getStatus()).isEqualTo(200);
367	        assertThat(replay.getResponse().getStatus()).isEqualTo(200);
