        // 失败不占 commandKey：同键可用于另一组合法请求
        String aliquotKey = uniqueKey("ALQ");
        assertThat(apply("alice", requestId, aliquotKey,
                List.of(item(s1, 1), item(s2, 1))).getResponse().getStatus()).isEqualTo(201);
    }
