/**
 * 并发唯一冲突后等待获胜事务提交的最长时间：约 2 秒（40 次 × 50ms）。
 */
private static final int REPLAY_WAIT_MILLIS = 50;
private static final int REPLAY_WAIT_ATTEMPTS = 40;

/**
